INSERT INTO permission (id, name, code, module, action)
SELECT 'b1000001-0000-0000-0000-000000000041', 'Org structure — View', 'ORG_STRUCTURE_VIEW', 'ORG_STRUCTURE', 'VIEW'
WHERE NOT EXISTS (SELECT 1 FROM permission WHERE code = 'ORG_STRUCTURE_VIEW');

UPDATE permission SET name = 'User accounts — View' WHERE code = 'USERS_VIEW';
